-- Automatic pricing: offers may be generated by the system (no staff author), with their cost breakdown.
CREATE TYPE "OfferSource" AS ENUM ('MANUAL', 'AUTO');

ALTER TABLE "quotation_offers" DROP CONSTRAINT "quotation_offers_createdById_fkey";
ALTER TABLE "quotation_offers" ADD COLUMN "breakdown" JSONB,
ADD COLUMN "source" "OfferSource" NOT NULL DEFAULT 'MANUAL',
ALTER COLUMN "createdById" DROP NOT NULL;
ALTER TABLE "quotation_offers" ADD CONSTRAINT "quotation_offers_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
